-- ===== 20261026000036_student_logins.sql =====
-- Student logins: a child added by the office has no login; their parents (or the office) can give
-- them one when they're ready, by adding the child's email. The student-login Edge Function checks
-- with student_login_request, then creates the login with the child's own profile id, so
-- everything already tied to the child (parents, classes, activities, car line) carries over. The
-- child signs in with that email like anyone else (a 6-digit code). student_login_remove takes the
-- login away again; the child stays on the roster.

create table public.student_logins (
  student_id  uuid primary key references public.profiles (id) on delete cascade,
  email       text not null unique,
  invited_by  uuid references public.profiles (id) on delete set null,
  invited_at  timestamptz not null default now()
);
alter table public.student_logins enable row level security;
create policy "the child's parents and the office" on public.student_logins for select to authenticated
  using (app.can_manage_child(student_id));

/** Parents of the child, or people.family (with the authenticator), may give or take a login. */
create function app.require_login_manager(p_student uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if app.is_guardian_of(p_student) then return; end if;
  perform app.require_permission('people.family');
end $$;

/**
 * Before the student-login function creates the login: may the caller give this child one, with
 * this email? Records it and returns the child's name for the login.
 */
create function public.student_login_request(p_student uuid, p_email text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare kid profiles%rowtype; mail text := lower(trim(coalesce(p_email, '')));
begin
  perform app.require_login_manager(p_student);
  select * into kid from profiles where id = p_student;
  if not found or kid.school_role is distinct from 'student' then raise exception 'That isn''t a student.'; end if;
  if not kid.managed then raise exception '% already has a login.', kid.first_name; end if;
  if mail !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter the email address % will sign in with.', kid.first_name; end if;
  if exists (select 1 from auth.users where lower(email) = mail) then
    raise exception 'That email already has a KH Royals account. Use a different one for %.', kid.first_name;
  end if;
  if exists (select 1 from student_logins where email = mail and student_id <> p_student) then
    raise exception 'That email is already set up for another student.';
  end if;
  insert into student_logins (student_id, email, invited_by) values (p_student, mail, auth.uid())
  on conflict (student_id) do update set email = excluded.email, invited_by = excluded.invited_by, invited_at = now();
  perform app.audit(null, 'student.login_requested', p_student::text, jsonb_build_object('email', mail));
  return jsonb_build_object('studentId', p_student, 'email', mail, 'firstName', kid.first_name, 'lastName', kid.last_name);
end $$;

/** The child's login: their email, and when they last signed in (null = not yet). Parents and the office. */
create function public.student_login_status(p_student uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when app.can_manage_child(p_student) then (
    select jsonb_build_object('email', coalesce(l.email, u.email), 'invitedAt', l.invited_at,
                              'hasLogin', u.id is not null, 'signedInAt', u.last_sign_in_at)
    from (select p_student as id) s
    left join student_logins l on l.student_id = s.id
    left join auth.users u on u.id = s.id
    where l.student_id is not null or u.id is not null)
  end
$$;

/** Take a child's login away: they can't sign in anymore, but stay on the roster with their parents. */
create function public.student_login_remove(p_student uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform app.require_login_manager(p_student);
  if not exists (select 1 from profiles where id = p_student and school_role = 'student') then
    raise exception 'That isn''t a student.';
  end if;
  update profiles set managed = true where id = p_student;   -- so deleting the login keeps the profile
  delete from push_tokens where user_id = p_student;
  delete from auth.users where id = p_student;
  delete from student_logins where student_id = p_student;
  update profile_private set email = null where id = p_student;
  perform app.audit(null, 'student.login_removed', p_student::text);
end $$;

-- A new login with a child's id is that child's: keep their profile, mark it as having a login,
-- and email them how to sign in. Everyone else gets a fresh profile, as before.
create or replace function app.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare kid profiles%rowtype;
begin
  select * into kid from profiles where id = new.id;
  if found then
    update profiles set managed = false where id = new.id;
    insert into profile_private (id, email) values (new.id, new.email) on conflict (id) do update set email = excluded.email;
    insert into app.email_queue (to_email, subject, body) values (new.email,
      'Your KH Royals login is ready',
      concat_ws(E'\n\n',
        'Hi ' || trim(kid.first_name) || ',',
        'Your family set up Royals Connect for you: Kingdom Heights'' school app, with your classes, assignments, activities and school news.',
        'To sign in, open the KH Royals app (or https://royalrockinapps.github.io/khroyals/), tap Log in, and enter this email address: '
          || new.email || '. We''ll email you a 6-digit code. There''s no password to remember.',
        'Kingdom Heights Preparatory School'));
    return new;
  end if;
  insert into profiles (id, first_name, last_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'first_name', ''), coalesce(new.raw_user_meta_data->>'last_name', ''));
  insert into profile_private (id, email) values (new.id, new.email);
  return new;
end $$;

revoke all on function app.require_login_manager(uuid) from public, anon;
grant execute on function app.require_login_manager(uuid) to authenticated, service_role;
revoke all on function public.student_login_request(uuid, text), public.student_login_status(uuid), public.student_login_remove(uuid) from public, anon;
grant execute on function public.student_login_request(uuid, text), public.student_login_status(uuid), public.student_login_remove(uuid)
  to authenticated, service_role;

-- Reads go through row-level security; writes only through the functions above (and the Edge Function).
revoke all on public.student_logins from anon;
revoke insert, update, delete on public.student_logins from authenticated;
grant select on public.student_logins to authenticated;
grant all on public.student_logins to service_role;

insert into app.applied_migrations (name) values ('20261026000036_student_logins.sql') on conflict do nothing;

-- ===== 20261026000037_photo_gallery.sql =====
-- Photo gallery: staff post albums of school photos (events, games, field trips) that every
-- approved account can see: parents, students, family and staff. Photos live in the private
-- 'gallery' storage bucket under "<uploader id>/…"; the app shows them through signed links.
-- Any staff member can post; gallery.manage holders (and an album's creator) tidy up; push.send
-- holders can also let everyone know about a new album.

create or replace function public.permission_catalog() returns table (key text, label text, description text)
language sql immutable as $$
  values
    ('admins.manage',    'Manage admins',         'Make or remove admins, set tiers and grant permissions (director only).'),
    ('people.view',      'View people',           'See everyone''s contact email in the admin portal.'),
    ('people.approve',   'Approve sign-ups',      'Approve new accounts as parents, students or family.'),
    ('people.roles',     'Change roles',          'Set anyone''s school role, including teachers and staff.'),
    ('people.family',    'Families & rosters',    'Link parents and family to students, set grades, manage classes, class/team rosters and car line duty.'),
    ('groups.manage',    'Manage all groups',     'Act as owner of every group: settings, members, moderation.'),
    ('calendar.school',  'School calendar',       'Add, change and remove school-wide calendar events.'),
    ('push.send',        'Send notifications',    'Send push notifications to everyone, a role or any group.'),
    ('alerts.send',      'Send critical alerts',  'Send critical alerts (severe weather, an active threat, a dangerous situation) to every teacher and staff member, see who''s safe, and give the all clear.'),
    ('questions.manage', 'Route questions',       'See every question sent to the school, assign it to faculty or staff, and answer it.'),
    ('messages.review',  'Student messages',      'Read every Ask the Teacher conversation between students and teachers, for safety.'),
    ('sports.manage',    'Manage activities',     'Add activities (sports, theater, music, art, clubs) and seasons, set schedules, assign coaches and directors, and approve sign-ups.'),
    ('forms.send',       'Send forms',            'Send forms (permission slips, releases, acknowledgments) to any class, activity, grade or the whole school, and see every form''s signatures.'),
    ('people.delete',    'Delete accounts',       'Permanently delete someone''s account, with their posts and comments. Deleting an admin also needs Manage admins.'),
    ('gallery.manage',   'Manage photo gallery',  'Change or remove any photo album or photo, not just your own.'),
    ('audit.view',       'Activity log',          'Review the school-wide activity log.')
$$;

update public.admin_roles set permissions = permissions || 'gallery.manage'::text
where id in ('director', 'administrator') and not ('gallery.manage' = any (permissions));

create table public.gallery_albums (
  id          uuid primary key default gen_random_uuid(),
  title       text not null check (length(trim(title)) between 1 and 80),
  description text not null default '' check (length(description) <= 500),
  taken_on    date not null default current_date,
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now()
);
create index on public.gallery_albums (taken_on desc, created_at desc);

create table public.gallery_photos (
  id          uuid primary key default gen_random_uuid(),
  album_id    uuid not null references public.gallery_albums (id) on delete cascade,
  path        text not null unique,                  -- gallery bucket: "<uploader id>/<file>.jpg"
  width       int not null check (width > 0),
  height      int not null check (height > 0),
  caption     text not null default '' check (length(caption) <= 300),
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now()
);
create index on public.gallery_photos (album_id, created_at);

alter table public.gallery_albums enable row level security;
alter table public.gallery_photos enable row level security;
create policy "approved accounts see the gallery" on public.gallery_albums for select to authenticated
  using (app.school_role() is not null);
create policy "approved accounts see the gallery" on public.gallery_photos for select to authenticated
  using (app.school_role() is not null);

/** May the caller change this album (its creator, or gallery.manage)? */
create function app.can_edit_album(a uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_staff(u) and (exists (select 1 from gallery_albums where id = a and created_by = u) or app.has_permission('gallery.manage', u))
$$;

/** Staff: start an album. p_notify (push.send holders only) tells everyone it's there. */
create function public.gallery_album_save(p_id uuid, p_title text, p_description text, p_taken_on date, p_notify boolean default false)
returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid;
begin
  if not app.is_staff() then raise exception 'Only staff post to the photo gallery.' using errcode = '42501'; end if;
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the album a name, like "Fall Fest 2026".'; end if;
  if p_id is null then
    insert into gallery_albums (title, description, taken_on, created_by)
    values (trim(p_title), coalesce(trim(p_description), ''), coalesce(p_taken_on, current_date), auth.uid())
    returning id into new_id;
  else
    if not app.can_edit_album(p_id) then raise exception 'You can only change albums you started.' using errcode = '42501'; end if;
    update gallery_albums set title = trim(p_title), description = coalesce(trim(p_description), ''), taken_on = coalesce(p_taken_on, taken_on)
    where id = p_id returning id into new_id;
  end if;
  if p_notify then
    perform app.require_permission('push.send');
    insert into notifications (audience, title, body, data, created_by)
    values ('everyone', '📸 New photos: ' || trim(p_title), 'See the album in the KH Royals photo gallery.',
            jsonb_build_object('albumId', new_id), auth.uid());
  end if;
  return new_id;
end $$;

/** Staff: add uploaded photos to an album. Each path must be in the caller's own folder. */
create function public.gallery_add_photos(p_album uuid, p_photos jsonb) returns int
language plpgsql security definer set search_path = public as $$
declare ph jsonb; n int := 0;
begin
  if not app.is_staff() then raise exception 'Only staff post to the photo gallery.' using errcode = '42501'; end if;
  if not exists (select 1 from gallery_albums where id = p_album) then raise exception 'That album is gone.'; end if;
  if jsonb_typeof(p_photos) is distinct from 'array' or jsonb_array_length(p_photos) not between 1 and 100 then
    raise exception 'Add between 1 and 100 photos at a time.';
  end if;
  for ph in select * from jsonb_array_elements(p_photos) loop
    if (ph->>'path') is null or split_part(ph->>'path', '/', 1) <> auth.uid()::text then
      raise exception 'Upload photos to your own folder first.';
    end if;
    insert into gallery_photos (album_id, path, width, height, caption, created_by)
    values (p_album, ph->>'path', (ph->>'width')::int, (ph->>'height')::int, coalesce(trim(ph->>'caption'), ''), auth.uid());
    n := n + 1;
  end loop;
  return n;
end $$;

/** Remove a photo: whoever posted it, the album's creator, or gallery.manage. Returns its file path to delete. */
create function public.gallery_photo_delete(p_photo uuid) returns text
language plpgsql security definer set search_path = public as $$
declare ph gallery_photos%rowtype;
begin
  select * into ph from gallery_photos where id = p_photo;
  if not found then return null; end if;
  if not (ph.created_by = auth.uid() and app.is_staff()) and not app.can_edit_album(ph.album_id) then
    raise exception 'You can only remove photos you posted.' using errcode = '42501';
  end if;
  delete from gallery_photos where id = p_photo;
  return ph.path;
end $$;

/** Remove an album and its photos (its creator, or gallery.manage). Returns the file paths to delete. */
create function public.gallery_album_delete(p_album uuid) returns text[]
language plpgsql security definer set search_path = public as $$
declare paths text[]; t text;
begin
  if not app.can_edit_album(p_album) then raise exception 'You can only remove albums you started.' using errcode = '42501'; end if;
  select coalesce(array_agg(path), '{}') into paths from gallery_photos where album_id = p_album;
  delete from gallery_albums where id = p_album returning title into t;
  perform app.audit(null, 'gallery.album_deleted', p_album::text, jsonb_build_object('title', t, 'photos', cardinality(paths)));
  return paths;
end $$;

-- Files: approved accounts read; staff upload to their own folder; a file no photo points to
-- anymore can be removed by staff (after gallery_photo_delete / gallery_album_delete), and
-- uploaders can always remove their own.
insert into storage.buckets (id, name, public) values ('gallery', 'gallery', false) on conflict (id) do nothing;
create policy "gallery: approved accounts read" on storage.objects for select to authenticated
  using (bucket_id = 'gallery' and app.school_role() is not null);
create policy "gallery: staff upload to their own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'gallery' and app.is_staff() and (storage.foldername(name))[1] = auth.uid()::text);
create policy "gallery: remove your own, or files no photo uses" on storage.objects for delete to authenticated
  using (bucket_id = 'gallery' and app.is_staff() and ((storage.foldername(name))[1] = auth.uid()::text
         or not exists (select 1 from public.gallery_photos p where p.path = objects.name)));

revoke all on function app.can_edit_album(uuid, uuid) from public, anon;
grant execute on function app.can_edit_album(uuid, uuid) to authenticated, service_role;
revoke all on function public.gallery_album_save(uuid, text, text, date, boolean), public.gallery_add_photos(uuid, jsonb),
  public.gallery_photo_delete(uuid), public.gallery_album_delete(uuid) from public, anon;
grant execute on function public.gallery_album_save(uuid, text, text, date, boolean), public.gallery_add_photos(uuid, jsonb),
  public.gallery_photo_delete(uuid), public.gallery_album_delete(uuid) to authenticated, service_role;

-- Reads go through row-level security; writes only through the functions above.
revoke all on public.gallery_albums, public.gallery_photos from anon;
revoke insert, update, delete on public.gallery_albums, public.gallery_photos from authenticated;
grant select on public.gallery_albums, public.gallery_photos to authenticated;
grant all on public.gallery_albums, public.gallery_photos to service_role;

insert into app.applied_migrations (name) values ('20261026000037_photo_gallery.sql') on conflict do nothing;

-- ===== 20261026000038_gallery_categories_visibility.sql =====
-- Photo gallery: categories (Events, Sports, Field Trips…) and who sees an album: everyone at school
-- or staff only (e.g. while it's being put together). Staff-only albums, their photos and their files
-- are hidden from everyone but staff by row-level security and the storage policy, not just the app.

create table public.gallery_categories (
  id        uuid primary key default gen_random_uuid(),
  name      text not null unique check (length(trim(name)) between 1 and 40),
  icon      text not null default '📷',
  position  int not null default 0
);
insert into public.gallery_categories (name, icon, position) values
  ('Events', '🎉', 1), ('Sports', '🏆', 2), ('Fine Arts', '🎭', 3), ('Field Trips', '🚌', 4),
  ('Classroom', '📚', 5), ('Chapel', '⛪', 6), ('Clubs', '🧩', 7), ('Campus', '🏫', 8);

alter table public.gallery_albums
  add column category_id uuid references public.gallery_categories (id) on delete set null,
  add column visibility text not null default 'everyone' check (visibility in ('everyone', 'staff'));
update public.gallery_albums set category_id = (select id from public.gallery_categories where name = 'Events') where category_id is null;

alter table public.gallery_categories enable row level security;
create policy "approved accounts see the categories" on public.gallery_categories for select to authenticated
  using (app.school_role() is not null);

/** Can this person see this album? Everyone approved for "everyone" albums; staff for all. */
create function app.sees_album(a uuid, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select app.school_role(u) is not null
     and exists (select 1 from gallery_albums where id = a and (visibility = 'everyone' or app.is_staff(u)))
$$;

drop policy "approved accounts see the gallery" on public.gallery_albums;
drop policy "approved accounts see the gallery" on public.gallery_photos;
create policy "everyone approved, or staff for staff-only albums" on public.gallery_albums for select to authenticated
  using (app.school_role() is not null and (visibility = 'everyone' or app.is_staff()));
create policy "photos of albums you can see" on public.gallery_photos for select to authenticated
  using (app.sees_album(album_id));

-- Files follow their album: a photo (or its "_t" thumbnail) is readable only if its album is.
drop policy "gallery: approved accounts read" on storage.objects;
create policy "gallery: photos of albums you can see" on storage.objects for select to authenticated
  using (bucket_id = 'gallery' and app.school_role() is not null and (app.is_staff() or exists (
    select 1 from public.gallery_photos p
    where p.path = regexp_replace(objects.name, '_t\.jpg$', '.jpg') and app.sees_album(p.album_id))));

drop function public.gallery_album_save(uuid, text, text, date, boolean);
/**
 * Staff: start an album, or change one (its creator, or gallery.manage). p_visibility is
 * 'everyone' or 'staff'. p_notify (push.send holders, everyone-albums only) tells everyone it's there.
 */
create function public.gallery_album_save(
  p_id uuid, p_title text, p_description text, p_taken_on date, p_notify boolean default false,
  p_category uuid default null, p_visibility text default 'everyone'
) returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid;
begin
  if not app.is_staff() then raise exception 'Only staff post to the photo gallery.' using errcode = '42501'; end if;
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the album a name, like "Fall Fest 2026".'; end if;
  if coalesce(p_visibility, '') not in ('everyone', 'staff') then raise exception 'Choose who sees the album.'; end if;
  if p_category is null or not exists (select 1 from gallery_categories where id = p_category) then
    raise exception 'Pick a category for the album.';
  end if;
  if p_id is null then
    insert into gallery_albums (title, description, taken_on, created_by, category_id, visibility)
    values (trim(p_title), coalesce(trim(p_description), ''), coalesce(p_taken_on, current_date), auth.uid(), p_category, p_visibility)
    returning id into new_id;
  else
    if not app.can_edit_album(p_id) then raise exception 'You can only change albums you started.' using errcode = '42501'; end if;
    update gallery_albums set title = trim(p_title), description = coalesce(trim(p_description), ''),
      taken_on = coalesce(p_taken_on, taken_on), category_id = p_category, visibility = p_visibility
    where id = p_id returning id into new_id;
  end if;
  if p_notify then
    perform app.require_permission('push.send');
    if p_visibility <> 'everyone' then raise exception 'Show the album to everyone before letting everyone know.'; end if;
    insert into notifications (audience, title, body, data, created_by)
    values ('everyone', '📸 New photos: ' || trim(p_title), 'See the album in the KH Royals photo gallery.',
            jsonb_build_object('albumId', new_id), auth.uid());
  end if;
  return new_id;
end $$;

/** gallery.manage: add a category (p_id null), rename one, or move it in the list. */
create function public.gallery_category_save(p_id uuid, p_name text, p_icon text default '📷', p_position int default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare new_id uuid;
begin
  perform app.require_permission('gallery.manage');
  if coalesce(trim(p_name), '') = '' then raise exception 'Name the category.'; end if;
  if exists (select 1 from gallery_categories where lower(name) = lower(trim(p_name)) and id is distinct from p_id) then
    raise exception 'There''s already a "%" category.', trim(p_name);
  end if;
  if p_id is null then
    insert into gallery_categories (name, icon, position)
    values (trim(p_name), coalesce(nullif(trim(p_icon), ''), '📷'), coalesce(p_position, (select coalesce(max(position), 0) + 1 from gallery_categories)))
    returning id into new_id;
  else
    update gallery_categories set name = trim(p_name), icon = coalesce(nullif(trim(p_icon), ''), icon), position = coalesce(p_position, position)
    where id = p_id returning id into new_id;
  end if;
  return new_id;
end $$;

/** gallery.manage: remove a category; its albums move to another one (p_move_to). */
create function public.gallery_category_delete(p_id uuid, p_move_to uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform app.require_permission('gallery.manage');
  if p_move_to is null or p_move_to = p_id or not exists (select 1 from gallery_categories where id = p_move_to) then
    raise exception 'Pick the category its albums move to.';
  end if;
  update gallery_albums set category_id = p_move_to where category_id = p_id;
  delete from gallery_categories where id = p_id;
end $$;

revoke all on function app.sees_album(uuid, uuid) from public, anon;
grant execute on function app.sees_album(uuid, uuid) to authenticated, service_role;
revoke all on function public.gallery_album_save(uuid, text, text, date, boolean, uuid, text),
  public.gallery_category_save(uuid, text, text, int), public.gallery_category_delete(uuid, uuid) from public, anon;
grant execute on function public.gallery_album_save(uuid, text, text, date, boolean, uuid, text),
  public.gallery_category_save(uuid, text, text, int), public.gallery_category_delete(uuid, uuid) to authenticated, service_role;

revoke all on public.gallery_categories from anon;
revoke insert, update, delete on public.gallery_categories from authenticated;
grant select on public.gallery_categories to authenticated;
grant all on public.gallery_categories to service_role;

insert into app.applied_migrations (name) values ('20261026000038_gallery_categories_visibility.sql') on conflict do nothing;

